import { readFileSync, readdirSync, statSync, existsSync } from 'fs';
import { join, dirname } from 'path';
import { DOC_TO_BUILDERS } from './doc-map.mjs';

// Re-exported for existing importers (this file used to define the table itself) and for
// `check-docs-vs-manifest.test.ts`, which asserts its shape.
export { DOC_TO_BUILDERS };

/**
 * Build-time (well, doc-time) guard: `.agent/components/**\/*.md` is the
 * human-facing description of the builder grammar; `dist/component-manifest.json`
 * (generated by generate-manifest.mjs from the built `.d.ts` files) is the
 * machine-facing one. They drift — Task 4's background note lists three real
 * cases from the 2026-09-02 bake-off (a doc describing a method the shipped
 * types didn't have yet, a doc describing behaviour the code didn't match).
 * This script is the cross-check: every documented builder-method token found
 * in a doc file must exist in the manifest entry of the builder(s) that file
 * documents.
 *
 * IMPORTANT — read before running: this script only READS
 * `dist/component-manifest.json`; it never runs `generate-manifest.mjs`
 * itself (running the generator from inside a `verify` step that may run
 * against a half-built `dist/` would silently overwrite a good manifest with
 * a near-empty one — see the `verify` script in package.json, which does not
 * chain it). Run `npm run build` first; `main()` below checks the manifest's
 * mtime against every built `.d.ts` under `dist/` and exits 1 with a plain
 * "run npm run build first" message — no raw ENOENT — if the manifest is
 * missing or stale relative to them.
 *
 * DOC_TO_BUILDERS (now defined in `./doc-map.mjs`, shared with
 * `generate-manifest.mjs`'s `loadAgentDoc`) is the explicit map required by the plan
 * (Task 4 Step 1): every file under `.agent/components/**` must have an entry. A doc file
 * with `null` documents no builder (a concept/internals guide — e.g. how the grid's
 * internal `GridRow` class works, not a public builder) and is skipped entirely. `main()`
 * below treats both a doc file missing from this map, and a map entry with no matching
 * doc file (a stale entry left behind by a deleted/renamed doc), as build errors — and
 * an entry that IS present but has an empty `[]` value (ambiguous between "documents a
 * builder" and `null`) as a build error too.
 *
 * `generate-manifest.mjs` now recurses into nested `dist/<component>/**` directories
 * (`chart/builders/`, `grid/columns/`) and matches `export interface`/`export declare
 * interface` bodies as well as `export declare class` ones, so every builder listed in
 * `doc-map.mjs` — including the nested-directory classes (`AxisBuilder`,
 * `LineChartBuilder`/`BarChartBuilder`/`AreaChartBuilder`, every grid `*ColumnBuilder`,
 * `ColumnsBuilder`) and the inline-builder interfaces (`SlotBuilder`,
 * `SidebarItemBuilder`, `SidebarFooterBuilder`, `SidebarMenuBuilder`,
 * `SidebarMenuItemBuilder`) — is now visible in `dist/component-manifest.json`. The
 * WARN class below is expected to be empty on a clean build; it stays as a safety net for
 * a future doc that names a builder before the corresponding code ships.
 *
 * WARN vs FAIL: a builder that never appears in the manifest at all can't tell us
 * anything — every method documented for it is unavoidably "missing", so that's a WARN,
 * printed but not fatal (exit 0 for that class of miss). A builder that DOES appear in
 * the manifest but is missing a specific documented method is real, actionable drift, so
 * that's a FAIL. Multi-builder docs (e.g. `grid/actions-builder.md` covers both
 * `ActionBuilder` and `ActionsBuilder`) are WARN only if NONE of their builders appear in
 * the manifest; if at least one does, a method missing from all of them is a FAIL,
 * printed against the full `Builder1|Builder2` list rather than guessing which one it
 * "really" belongs to.
 *
 * Only `with*`/`add*`/`as*`/`build` tokens are ever considered — see
 * extractMethodTokens below.
 */

/**
 * Extract the *content* of every fenced code block in the markdown, as a flat array of
 * strings. The fence-open line is matched permissively (any info string, optional `\r`)
 * since Markdown allows ` ```ts `, ` ```typescript `, ` ``` ` (no info string), or a
 * Windows-style `\r\n` line ending — an info-string-specific or bare-`\n` pattern would
 * silently fail to strip (and thus double-scan) any fence that doesn't match it exactly.
 */
export function extractFencedBlocks(markdown) {
    const blocks = [];
    const fencedRe = /```[^\n]*\r?\n([\s\S]*?)```/g;
    let match;
    while ((match = fencedRe.exec(markdown)) !== null) {
        blocks.push(match[1]);
    }
    return blocks;
}

/**
 * Extract the *content* of every inline code span (single backticks) in the markdown, as a
 * flat array of strings — fenced blocks are stripped first so a backtick that's part of a
 * ``` fence marker is never mistaken for an inline span's start/end.
 */
export function extractInlineSpans(markdown) {
    const fencedRe = /```[^\n]*\r?\n([\s\S]*?)```/g;
    const fencedRanges = [];
    let match;
    while ((match = fencedRe.exec(markdown)) !== null) {
        fencedRanges.push([match.index, match.index + match[0].length]);
    }

    let withoutFences = '';
    let cursor = 0;
    for (const [start, end] of fencedRanges) {
        withoutFences += markdown.slice(cursor, start);
        cursor = end;
    }
    withoutFences += markdown.slice(cursor);

    const spans = [];
    const inlineRe = /`([^`\n]+)`/g;
    while ((match = inlineRe.exec(withoutFences)) !== null) {
        spans.push(match[1]);
    }
    return spans;
}

/**
 * Extract the *content* of every fenced code block and every inline code span in the
 * markdown, as a flat array of strings, regardless of which kind each came from. Kept for
 * callers (`extractMethodTokens`) that only need every candidate token in the doc without
 * caring where it came from; `checkDoc` uses `extractFencedBlocks`/`extractInlineSpans`
 * directly since fenced and inline regions are checked differently (see checkDoc's doc
 * comment).
 */
export function extractCodeRegions(markdown) {
    return [...extractFencedBlocks(markdown), ...extractInlineSpans(markdown)];
}

/**
 * Only a token that LOOKS like a builder method per `.agent/builder-pattern.md`
 * ("Builder methods return `this`" / "only `with*`, `add*`, `as*`, `build`")
 * is ever a candidate — `with`/`add`/`as` immediately followed by a capital
 * letter (so `withCaption`, `addAction`, `asGlass` match but `without` and a
 * bare `with` do not), or the exact literal `build`. Everything else —
 * native DOM/CSS/RxJS/Math calls (`preventDefault`, `forEach`, `showModal`,
 * `clamp`, `var`, `rgba`), instance methods that don't follow the builder
 * naming convention (`select`, `open`, `close`, `show` on the built
 * element), and internal helper functions (`_position`, `buildTextField` —
 * `\b` plus the exact-`build` alternative means a `build`-prefixed longer
 * identifier like `buildTextField` does NOT match the same way `build` does)
 * — is ignored outright. This replaces an earlier allow-list approach: an
 * enumerated list of exceptions is a losing game (every native/DOM/CSS call
 * anyone might cite in an example is a potential omission), where filtering
 * by the *positive* naming rule the codebase already enforces is exhaustive
 * by construction. `generate-manifest.mjs` independently skips any
 * `_`-prefixed member (see its extractMethods), so a leading underscore is
 * excluded on both sides of this comparison without needing a special case
 * here.
 */
const METHOD_TOKEN_RE = /\b((?:with|add|as)[A-Z]\w*|build)\(/g;

export function extractMethodTokens(markdown) {
    const tokens = new Set();
    for (const region of extractCodeRegions(markdown)) {
        // matchAll takes its own copy of the regex per call, so there is no
        // shared `lastIndex` to reset between regions (unlike a module-level
        // regex reused across exec() calls).
        for (const match of region.matchAll(METHOD_TOKEN_RE)) {
            tokens.add(match[1]);
        }
    }
    return [...tokens];
}

/**
 * List every `.md` file under `baseDir`, recursively, relative to it with forward-slash
 * separators (so the DOC_TO_BUILDERS keys above, written as `grid/grid.md`, match on every
 * platform this runs on).
 */
function listDocFilesRecursive(baseDir) {
    const out = [];
    for (const entry of readdirSync(baseDir)) {
        const full = join(baseDir, entry);
        if (statSync(full).isDirectory()) {
            out.push(...listDocFilesRecursive(full).map((f) => `${entry}/${f}`));
        } else if (entry.endsWith('.md')) {
            out.push(entry);
        }
    }
    return out;
}

/**
 * List every doc file this check reads: every `.md` under `.agent/components` (recursively
 * — see listDocFilesRecursive), plus `.agent/router.md` explicitly. Router docs live one
 * level above `.agent/components`, not inside it (`.agent/router.md`, a sibling of the
 * `components/` directory, not a descendant) — `doc-map.mjs` maps it under the key
 * `'../router.md'` (relative to `baseDir`, the same way `join(baseDir, '../router.md')`
 * resolves it back to the real file), so it's included here by explicit, one-off lookup
 * rather than by walking upward generically (which would also pull in every other loose
 * `.agent/*.md` file this check has no business validating).
 */
export function listDocFiles(baseDir) {
    const out = listDocFilesRecursive(baseDir);
    const routerDocPath = join(baseDir, '..', 'router.md');
    if (existsSync(routerDocPath) && statSync(routerDocPath).isFile()) {
        out.push('../router.md');
    }
    return out;
}

/** Map manifest component name → Set of its method names. */
export function buildManifestIndex(manifest) {
    const index = new Map();
    for (const component of manifest.components) {
        index.set(component.name, new Set(component.methods.map((m) => m.name)));
    }
    return index;
}

/**
 * Recursively find the newest mtime (ms) among every `.d.ts` file under
 * `dir`. Returns `-Infinity` if `dir` doesn't exist or contains none — a
 * sentinel that always compares "older" than any real manifest mtime, so
 * callers don't need a separate "no .d.ts found" branch.
 */
export function findNewestDtsMtime(dir) {
    let newest = -Infinity;
    let entries;
    try {
        entries = readdirSync(dir, { withFileTypes: true });
    } catch {
        return newest;
    }
    for (const entry of entries) {
        const full = join(dir, entry.name);
        if (entry.isDirectory()) {
            newest = Math.max(newest, findNewestDtsMtime(full));
        } else if (entry.name.endsWith('.d.ts')) {
            newest = Math.max(newest, statSync(full).mtimeMs);
        }
    }
    return newest;
}

/**
 * A `new <Name>Builder` constructor call: matches just `new <Name>Builder` (plus any
 * trailing whitespace) via a sticky regex; a possible generic-argument list and the
 * mandatory following `(` are then validated by `matchNewBuilder` below, not by this
 * regex itself — nested generics (`new GridBuilder<Row<T>>()`) cannot be matched by a
 * single non-recursive regex (`<[^>]*>` stops at the FIRST `>`, which is the inner one),
 * so that part needs real balanced-bracket counting instead.
 */
const NEW_KEYWORD_RE = /new\s+(\w+Builder)\s*/y;

/**
 * Try to match `new <Name>Builder(...)`'s constructor call starting at position `i` in
 * `code`, including an optional balanced generic-argument list between the name and the
 * mandatory `(` (`new GridBuilder<Row<T>>(`). Returns `{ name, length }` (the number of
 * characters consumed, for the caller to advance its scan position by) or `null` if
 * nothing matches at `i` — including the case where a generic-looking `<...>` follows the
 * name but isn't itself followed by `(` (not actually a constructor call at this
 * position, e.g. a bare type reference).
 */
function matchNewBuilder(code, i) {
    NEW_KEYWORD_RE.lastIndex = i;
    const m = NEW_KEYWORD_RE.exec(code);
    if (!m) return null;

    let end = NEW_KEYWORD_RE.lastIndex;
    if (code[end] === '<') {
        let depth = 0;
        let j = end;
        for (; j < code.length; j++) {
            if (code[j] === '<') {
                depth++;
            } else if (code[j] === '>') {
                depth--;
                if (depth === 0) {
                    j++;
                    break;
                }
            }
        }
        end = j;
        while (end < code.length && /\s/.test(code[end])) end++;
    }

    if (code[end] !== '(') return null;
    return { name: m[1], length: end - i };
}

/**
 * A candidate builder-method call token, same shape as METHOD_TOKEN_RE but non-consuming
 * (its own opening `(` is left for attributeFencedCallTokens's uniform per-character depth
 * scan) and sticky so it can be tried at an exact scan position. The leading `\b` matters:
 * without it, a sticky match attempted mid-identifier can still succeed — `node.hasAttribute(`
 * scanned character-by-character reaches the `A` of `Attribute`, and `as` + `[A-Z]` happily
 * matches the `sA` sitting right before it (`ha` + `sAttribute` bridges into `asAttribute`),
 * same failure mode for `foo.rebuild()` matching bare `build`. `\b` requires the match to
 * start at an actual word boundary, so a position in the middle of `hasAttribute` or
 * `rebuild` (word char on both sides) can never begin a match.
 */
const CALL_TOKEN_STICKY_RE = /\b((?:with|add|as)[A-Z]\w*|build)(?=\()/y;

/**
 * `(?:const|let) NAME = new <Name>Builder` assignments, scanned once up front over the
 * whole fenced block (not sticky — every match anywhere in the code, not just at a given
 * position) so `attributeFencedCallTokens` knows which bare variable names are aliases for
 * a builder instance before it does its single left-to-right pass. This is what lets
 * `layout.addSlot()` (a later, separate statement referencing `layout`) resolve back to
 * `LayoutBuilder`, matching `.agent/components/layout.md`'s real shape: `const layout = new
 * LayoutBuilder()...; ...; layout.addSlot().withContent(...);`.
 */
const VAR_ASSIGNMENT_RE = /\b(?:const|let)\s+(\w+)\s*=\s*new\s+(\w+Builder)\b/g;

/**
 * `IDENT.` where `IDENT` is a scan-time candidate for a tracked variable (see
 * VAR_ASSIGNMENT_RE) — sticky, sitting between matchNewBuilder and CALL_TOKEN_STICKY_RE in
 * attributeFencedCallTokens's per-position matcher chain. Only the identifier is captured;
 * the `.` itself is left for the fallback per-character scan (it isn't `(`, `)`, `;`, or
 * `\n`, so it's a harmless single-character advance either way).
 */
const IDENT_DOT_RE = /\b(\w+)\.(?=\w)/y;

/**
 * Methods whose return type is itself a builder (`ComponentBuilder`-typed inline builders,
 * per `.agent/builder-pattern.md`'s "with* / add* methods can return another builder
 * instance" pattern), keyed by method name. When a call to one of these is scanned, the
 * builder it returns becomes the receiver for whatever's chained directly after it in the
 * same block (see the "chain type change" step in attributeFencedCallTokens) — e.g.
 * `layout.addSlot().withContent(...)`: `addSlot()` returns a `SlotBuilder`, so
 * `withContent` must be checked against `SlotBuilder`, not `LayoutBuilder`.
 *
 * This is deliberately a static fallback, not a read of the manifest's own
 * `methods[].returnType` — attributeFencedCallTokens is a pure function of the fenced
 * code's text alone (no manifest passed in), and threading the manifest through here just
 * to resolve a handful of well-known sub-builder methods would be a lot of new surface
 * for a small, stable list. `add*Column` -> `*ColumnBuilder` is handled generically below
 * (returnTypeFor), not listed here, since it would otherwise need one entry per grid
 * column type.
 */
const RETURN_TYPE_TABLE = {
    addSlot: 'SlotBuilder',
    withToolbar: 'ToolbarBuilder',
    withPrimaryButton: 'ButtonBuilder',
    addSecondaryButton: 'ButtonBuilder',
    addTextButton: 'ButtonBuilder',
    addRoute: 'RouteBuilder',
    addItem: 'SidebarItemBuilder',
    withFooter: 'SidebarFooterBuilder',
    withYAxis: 'AxisBuilder',
    withSecondaryYAxis: 'AxisBuilder',
    withXAxis: 'AxisBuilder',
    addLine: 'LineChartBuilder',
    addBar: 'BarChartBuilder',
    addArea: 'AreaChartBuilder',
};

/** The builder a call returns, per RETURN_TYPE_TABLE or the generic `add<X>Column` ->
 * `<X>ColumnBuilder` grid pattern, or `null` if `methodName` isn't known to return one. */
function returnTypeFor(methodName) {
    if (RETURN_TYPE_TABLE[methodName]) return RETURN_TYPE_TABLE[methodName];
    const columnMatch = methodName.match(/^add(\w+)Column$/);
    return columnMatch ? `${columnMatch[1]}ColumnBuilder` : null;
}

/**
 * Scan one fenced code block and attribute each candidate with*, add*, as*, build call to
 * the builder it's actually chained off of in that snippet — composed examples build more
 * than one builder in the same block (`new PanelBuilder().withContent(new
 * LabelBuilder().withCaption(...))`), and a call chained off the INNER builder must not be
 * checked against the OUTER one's methods (the false-positive `PanelBuilder.withCaption
 * not in manifest` this exists to avoid).
 *
 * A left-to-right, position-by-position scan tracks paren depth and a receiver stack.
 * At each position, in order:
 *  1. `new <Name>Builder(...)` (matchNewBuilder, handles nested generics) pushes `{ name,
 *     depth }` at the CURRENT depth — so the receiver stays active across its own
 *     top-level chain (e.g. `.asGlass()` right after `new PanelBuilder()`), and is only
 *     popped once the scan returns to a depth at or below where it was pushed (i.e. once
 *     whatever argument list it was nested inside, if any, has closed).
 *  2. `IDENT.` where `IDENT` is a tracked variable (VAR_ASSIGNMENT_RE, populated by a
 *     pre-pass over the whole block) pushes that variable's builder the same way `new`
 *     does — this is what makes a LATER, separate statement like `layout.addSlot()...`
 *     resolve back to `LayoutBuilder` after `const layout = new LayoutBuilder()...;`.
 *  3. A call token (CALL_TOKEN_STICKY_RE) is attributed to whichever receiver is on top of
 *     the stack, or `null` if the stack is empty (e.g. `columns.addTrendColumn(...)` where
 *     `columns` was never assigned from `new ...Builder()` anywhere in this block). If the
 *     call's method name has a known return-builder (returnTypeFor — the "chain type
 *     change" step), that is recorded as a PENDING switch (`pendingSwitches`), not pushed
 *     onto the receiver stack immediately — see the next point for why.
 *  4. `;` at depth 0 clears the receiver stack (and any still-open pending switches)
 *     entirely — nothing after a top-level semicolon can still be "chained off" whatever
 *     was active before it.
 *  5. A newline at depth 0 whose next non-whitespace character is NOT `.` also clears the
 *     stack (and pending switches) — the common semicolon-less doc-example style (a chain
 *     that just ends at end-of-line, with the next line starting an unrelated statement)
 *     needs the same reset `;` gives it; a chain that DOES continue on the next line
 *     (leading `.`, the usual multi-line style throughout `.agent/components/**`) is left
 *     alone.
 *  6. `(` increments depth. `)` decrements it, pops any stack entries recorded deeper than
 *     the new depth, THEN resolves every pending switch whose `afterDepth` equals the new
 *     depth — i.e. exactly when that switch's own triggering call has fully closed its
 *     argument list. A pending switch is applied (pushed onto the stack) only if nothing
 *     was pushed onto the receiver stack anywhere inside its argument list (see
 *     `contaminated`, set whenever step 1 or 2 fires while a switch is still pending) —
 *     otherwise it's discarded. This is what makes `withToolbar(new ToolbarBuilder()...)`
 *     behave differently from `addSlot()`/`addTextColumn('name')`: the former's argument
 *     itself builds a DIFFERENT concrete instance via `new`, so treating `withToolbar`'s
 *     hypothetical return value as the active receiver for whatever's chained AFTER it
 *     would be wrong (and, before this fix, is exactly how a `new ToolbarBuilder()` nested
 *     three levels deep inside a `withToolbar(...)` argument leaked out and misattributed a
 *     later, unrelated `.withCaption('Grid')`/`.build()` on the OUTER builder); the
 *     latter's arguments are plain values (a string literal), so nothing contaminates the
 *     switch and it applies normally.
 */
export function attributeFencedCallTokens(code) {
    const variables = new Map();
    for (const m of code.matchAll(VAR_ASSIGNMENT_RE)) {
        variables.set(m[1], m[2]);
    }

    const results = [];
    const stack = [];
    // Chain-type-change switches (returnTypeFor) not yet resolved — each is
    // `{ afterDepth, name, contaminated }`: `afterDepth` is the depth its triggering call
    // was found at (and therefore the depth the scan must return to, via a matching `)`,
    // before the switch can apply); `contaminated` is set true the moment ANYTHING is
    // pushed onto `stack` (a `new` or tracked-variable receiver) while this switch is still
    // open — see the function doc comment above for why a contaminated switch is discarded
    // rather than applied.
    const pendingSwitches = [];
    let depth = 0;
    let i = 0;

    while (i < code.length) {
        if (depth === 0 && code[i] === ';') {
            stack.length = 0;
            pendingSwitches.length = 0;
            i++;
            continue;
        }

        if (depth === 0 && code[i] === '\n') {
            let j = i + 1;
            while (j < code.length && /\s/.test(code[j])) j++;
            if (code[j] !== '.') {
                stack.length = 0;
                pendingSwitches.length = 0;
            }
            i++;
            continue;
        }

        const newMatch = matchNewBuilder(code, i);
        if (newMatch) {
            for (const pending of pendingSwitches) pending.contaminated = true;
            stack.push({ name: newMatch.name, depth });
            i += newMatch.length;
            continue;
        }

        IDENT_DOT_RE.lastIndex = i;
        const identMatch = IDENT_DOT_RE.exec(code);
        if (identMatch && variables.has(identMatch[1])) {
            for (const pending of pendingSwitches) pending.contaminated = true;
            stack.push({ name: variables.get(identMatch[1]), depth });
            i += identMatch[1].length;
            continue;
        }

        CALL_TOKEN_STICKY_RE.lastIndex = i;
        const callMatch = CALL_TOKEN_STICKY_RE.exec(code);
        if (callMatch) {
            const token = callMatch[1];
            const receiver = stack.length > 0 ? stack[stack.length - 1].name : null;
            results.push({ token, receiver });
            i += callMatch[0].length;

            const nextReceiver = returnTypeFor(token);
            if (nextReceiver) {
                pendingSwitches.push({ afterDepth: depth, name: nextReceiver, contaminated: false });
            }
            continue;
        }

        const ch = code[i];
        if (ch === '(') {
            depth++;
        } else if (ch === ')') {
            depth--;
            while (stack.length > 0 && stack[stack.length - 1].depth > depth) {
                stack.pop();
            }
            // Resolve (in nesting order, innermost first) every pending switch whose
            // triggering call's argument list has now fully closed back to the depth it
            // was found at.
            for (let k = pendingSwitches.length - 1; k >= 0; k--) {
                if (pendingSwitches[k].afterDepth !== depth) continue;
                const pending = pendingSwitches[k];
                pendingSwitches.splice(k, 1);
                if (!pending.contaminated) {
                    stack.push({ name: pending.name, depth });
                }
            }
        }
        i++;
    }

    return results;
}

/**
 * A qualified inline mention — `` `XBuilder.method(` `` — found in prose (e.g.
 * `.agent/components/grid/trend-column.md`'s ``` `TrendBuilder.withTrend()` ``` mentioning
 * a DIFFERENT builder than the doc's own `TrendColumnBuilder`, or `text-field.md` citing
 * ``` `TextFieldBuilder.asInlineError()` ``` correctly). Global (not sticky) — every
 * qualified mention in a span, scanned in one pass.
 */
const QUALIFIED_INLINE_RE = /\b(\w+Builder)\.((?:with|add|as)[A-Z]\w*|build)\(/g;

/**
 * Check one doc file's markdown against DOC_TO_BUILDERS + the manifest index.
 * Returns { failures, warnings, checked }.
 *
 * Inline code spans (prose/bullets) split into two cases:
 *  - Qualified (`` `XBuilder.method(...)` ``, matched by QUALIFIED_INLINE_RE): the doc is
 *    citing a SPECIFIC builder's method, possibly not even one of this doc's own mapped
 *    `builders` (e.g. a doc mentioning another component's API for context) — checked
 *    directly against `XBuilder`'s manifest methods, the same way a fenced `new
 *    XBuilder(...)` chain is (see below); skipped entirely if `XBuilder` isn't in the
 *    manifest at all, same reasoning as the fenced-block skip case.
 *  - Unqualified (a bare `` `method(...)` ``): keeps the original whole-doc attribution —
 *    checked against `builders` (this doc's own mapped builder(s)). A miss is a WARN (not
 *    a FAIL) when NONE of `builders` appear in the manifest at all (the manifest
 *    structurally can't confirm or deny anything about them — see the module doc comment),
 *    and a FAIL when at least one does but still lacks the method.
 *
 * Fenced code blocks are attributed per-call instead, via attributeFencedCallTokens: a call
 * chained off a builder resolved in that block (a `new <Name>Builder(...)`, a tracked
 * variable, or a return-type chain switch) is checked against THAT builder's manifest
 * methods directly, always as a FAIL when it misses, never a WARN, since the receiver is
 * only ever checked once it's confirmed present in the manifest. A call with no resolvable
 * receiver is skipped entirely — not counted, not checked.
 *
 * `checked` counts every candidate token actually compared against a manifest entry —
 * unqualified inline tokens (deduped by name, one whole-doc attribution), qualified inline
 * tokens and fenced tokens (both deduped by `receiver.token` pair, since the same call
 * shape can legitimately recur across multiple snippets/mentions in one doc) — skipped
 * tokens (no resolvable receiver, or a receiver absent from the manifest) are not counted.
 */
export function checkDoc(docFile, markdown, builders, manifestIndex) {
    const failures = [];
    const warnings = [];
    let checked = 0;
    const anyBuilderPresent = builders.some((b) => manifestIndex.has(b));
    const label = builders.length > 1 ? builders.join('|') : builders[0];

    const seenQualifiedChecks = new Set();
    const inlineTokens = new Set();
    for (const span of extractInlineSpans(markdown)) {
        for (const [, receiver, method] of span.matchAll(QUALIFIED_INLINE_RE)) {
            if (!manifestIndex.has(receiver)) continue;
            const key = `${receiver}.${method}`;
            if (seenQualifiedChecks.has(key)) continue;
            seenQualifiedChecks.add(key);
            checked++;
            if (manifestIndex.get(receiver)?.has(method)) continue;
            failures.push(`${docFile}: ${receiver}.${method} not in manifest`);
        }

        // Unqualified bare spans keep the original whole-doc attribution — strip out
        // whatever QUALIFIED_INLINE_RE already accounted for above so the same method
        // name isn't double-counted under both attribution rules.
        const withoutQualified = span.replace(QUALIFIED_INLINE_RE, '');
        for (const match of withoutQualified.matchAll(METHOD_TOKEN_RE)) {
            inlineTokens.add(match[1]);
        }
    }
    for (const method of inlineTokens) {
        checked++;
        const foundInAny = builders.some((b) => manifestIndex.get(b)?.has(method));
        if (foundInAny) continue;
        const line = `${docFile}: ${label}.${method} not in manifest`;
        (anyBuilderPresent ? failures : warnings).push(line);
    }

    const seenFencedChecks = new Set();
    for (const block of extractFencedBlocks(markdown)) {
        for (const { token, receiver } of attributeFencedCallTokens(block)) {
            if (!receiver || !manifestIndex.has(receiver)) continue;
            const key = `${receiver}.${token}`;
            if (seenFencedChecks.has(key)) continue;
            seenFencedChecks.add(key);
            checked++;
            if (manifestIndex.get(receiver)?.has(token)) continue;
            failures.push(`${docFile}: ${receiver}.${token} not in manifest`);
        }
    }

    return { failures, warnings, checked };
}

// Resolved from process.argv[1] (this script's own path), not import.meta.url:
// TypeScript's CommonJS transpile (used to run this .mjs file under Jest — see
// jest-mjs-transformer.cjs) can't represent import.meta, so main() — only ever
// reached via direct CLI invocation, see invokedDirectly below — must not
// depend on it. Same pattern as check-css-globals.mjs's main().
function main(scriptPath) {
    const distDir = join(dirname(scriptPath), '../dist');
    const agentComponentsDir = join(dirname(scriptPath), '../../../.agent/components');
    const manifestPath = join(distDir, 'component-manifest.json');

    let manifestMtimeMs;
    try {
        manifestMtimeMs = statSync(manifestPath).mtimeMs;
    } catch {
        console.error('check-docs-vs-manifest: dist/component-manifest.json not found — run `npm run build` first.');
        process.exit(1);
    }

    const newestDtsMtimeMs = findNewestDtsMtime(distDir);
    if (newestDtsMtimeMs > manifestMtimeMs) {
        console.error('check-docs-vs-manifest: dist/component-manifest.json is older than the built .d.ts files — run `npm run build` first.');
        process.exit(1);
    }

    let manifest;
    try {
        manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));
    } catch (err) {
        console.error('check-docs-vs-manifest: dist/component-manifest.json could not be parsed — run `npm run build` again.');
        console.error(err.message);
        process.exit(1);
    }

    const emptyArrayEntries = Object.entries(DOC_TO_BUILDERS).filter(
        ([, builders]) => Array.isArray(builders) && builders.length === 0,
    );
    if (emptyArrayEntries.length > 0) {
        console.error('check-docs-vs-manifest: DOC_TO_BUILDERS entr(y/ies) with an empty [] value — ambiguous between "documents a builder" and "documents none"; use null for a concept guide, or list the builder(s):');
        for (const [f] of emptyArrayEntries) {
            console.error(`  - ${f}`);
        }
        process.exit(1);
    }

    const manifestIndex = buildManifestIndex(manifest);
    const docFiles = listDocFiles(agentComponentsDir).sort();
    const docFileSet = new Set(docFiles);

    const unregistered = docFiles.filter((f) => !(f in DOC_TO_BUILDERS));
    const stale = Object.keys(DOC_TO_BUILDERS).filter((f) => !docFileSet.has(f));
    if (unregistered.length > 0 || stale.length > 0) {
        if (unregistered.length > 0) {
            console.error('check-docs-vs-manifest: doc file(s) missing from DOC_TO_BUILDERS in check-docs-vs-manifest.mjs:');
            for (const f of unregistered) {
                console.error(`  - ${f}`);
            }
        }
        if (stale.length > 0) {
            console.error('check-docs-vs-manifest: DOC_TO_BUILDERS entr(y/ies) with no matching doc file under .agent/components (rename or delete these):');
            for (const f of stale) {
                console.error(`  - ${f}`);
            }
        }
        console.error('\nRegister every new doc under .agent/components/ in DOC_TO_BUILDERS (use null for a concept guide with no builder), and remove entries for docs that no longer exist.');
        process.exit(1);
    }

    let totalChecked = 0;
    const allFailures = [];
    const allWarnings = [];

    for (const docFile of docFiles) {
        const builders = DOC_TO_BUILDERS[docFile];
        if (builders === null) continue;

        const markdown = readFileSync(join(agentComponentsDir, docFile), 'utf8');
        const { failures, warnings, checked } = checkDoc(docFile, markdown, builders, manifestIndex);
        totalChecked += checked;
        allFailures.push(...failures);
        allWarnings.push(...warnings);
    }

    if (allWarnings.length > 0) {
        console.warn('check-docs-vs-manifest: WARN — documented methods on a builder that is entirely absent from dist/component-manifest.json (see the module doc comment for why: a structural gap in generate-manifest.mjs, not doc drift):');
        for (const w of allWarnings) {
            console.warn(`  - ${w}`);
        }
    }

    if (allFailures.length > 0) {
        console.error('check-docs-vs-manifest: FAIL — documented methods missing from a builder that IS present in dist/component-manifest.json:');
        for (const f of allFailures) {
            console.error(`  - ${f}`);
        }
    }

    console.log(`check-docs-vs-manifest: ${totalChecked} methods checked — ${allFailures.length} failure(s), ${allWarnings.length} warning(s).`);

    if (allFailures.length > 0) {
        process.exit(1);
    }
}

const invokedDirectly = process.argv[1]?.endsWith('check-docs-vs-manifest.mjs');
if (invokedDirectly) {
    main(process.argv[1]);
}
